/** Bind an idempotent gate lifecycle marker to its owning task, independent of the authentication protocol. */
export function setTaskGate(cargo,form,gate,active) {
   const state=cargo.forms && cargo.forms[form];
   const owner=state && cargo.forms[state.task];
   if(!owner || !gate)return false;
   if(active){owner.activeGates ||= {};owner.activeGates[gate]=true;}
   else if(owner.activeGates){delete owner.activeGates[gate];if(!Object.keys(owner.activeGates).length)delete owner.activeGates;}
   return true;
}
