/** Normalize spoken digits without interpreting numbers embedded in unrelated words. */
export function serviceDigits(text) {
   const words={zero:'0',cero:'0',one:'1',uno:'1',two:'2',dos:'2',three:'3',tres:'3',four:'4',cuatro:'4',five:'5',cinco:'5',six:'6',seis:'6',seven:'7',siete:'7',eight:'8',ocho:'8',nine:'9',nueve:'9'};
   return String(text || '').replace(/[a-záéíóúñ]+/gi,word=>Object.hasOwn(words,word.toLowerCase())?words[word.toLowerCase()]:word);
}
export function otpDigits(text) {
   const map={zero:'0',cero:'0',one:'1',uno:'1',two:'2',dos:'2',three:'3',tres:'3',four:'4',cuatro:'4',five:'5',cinco:'5',six:'6',seis:'6',seven:'7',siete:'7',eight:'8',ocho:'8',nine:'9',nueve:'9'};
   const filler=new Set(['el','mi','es','codigo','code','is','my','the','numero','number','a','ver']);
   const tokens=String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').split(/[\s,.;:!?-]+/).filter(t=>t&&!filler.has(t));
   const spoken=tokens.length && tokens.some(t=>Object.hasOwn(map,t)) && tokens.every(t=>/^\d+$/.test(t)||Object.hasOwn(map,t))?tokens.map(t=>map[t]??t).join(''):'';
   return spoken.length===6?spoken:String(text || '').replace(/\D/g,'');
}
export function contactPrompt(cargo,options,callerAllowed,partial=false,es=false) {
   if(partial)return es?'Continúe.':'Go on.';
   const verb=es?cargo.verb_es:cargo.verb;const account=options.account_pattern?(es?options.account_name_es || options.account_name:options.account_name):'';
   const alternative=account?(es?', o ':', or ')+account:'';
   const lead=cargo.contactIntroSkip || options.fromMenu?'':(es?options.intro_es || options.intro:options.intro)||'';
   const key=cargo.voice?(es?callerAllowed?' seguido de la tecla numeral':' seguido de la tecla numeral si se ingresó usando el teclado de marcación':callerAllowed?' followed by the pound key':' followed by the pound key if entered using the dial pad'):'';
   const question=callerAllowed?(es?`Para usar su identificador de llamadas, por favor ${verb} sí. De lo contrario, por favor ${verb}${cargo.voice?' o ingrese':''} el teléfono o correo electrónico asociado con su cuenta${alternative}${key}.`:`To use your caller id, please ${verb} yes. Otherwise, please ${verb}${cargo.voice?' or enter':''} the phone or email associated with your account${alternative}${key}.`):(es?`Por favor ${verb}${cargo.voice?' o ingrese':''} el teléfono o correo electrónico asociado con su cuenta${alternative}${key}.`:`Please ${verb}${cargo.voice?' or enter':''} the phone or email associated with your account${alternative}${key}.`);
   return (lead?lead+' ':'')+question+(es?` Para salir en cualquier momento, puede ${cargo.voice?'presionar la tecla de asterisco o decir':'escribir'} SALIR.`:` To exit anytime you can ${cargo.voice?'press the asterisk key or ':''}${verb} EXIT.`);
}
