/** Reenter the existing owning FORM or its gate without making the owner its own parent. */
export function identityResumeContext(forms,owner,target,identifiers={}) {
   const state=forms && forms[owner];
   if(state && state.definition===target && ['acct_number','cell_number','email'].some(key=>!!identifiers[key])){
      state.arguments ||= {};
      for(const key of ['acct_number','cell_number','email'])state.arguments[key]=String(identifiers[key] || '');
   }
   return state && state.definition===target?{form_instance:owner,parent_form:state.parent || '',result_input:state.result_input || ''}:{form_instance:'',parent_form:owner || '',result_input:''};
}
